const dictionaries: Record<Language, Dictionary> = { ru: {}, kk, en };

function interpolate(value: string, variables?: Record<string, string | number>) {
  if (!variables) return value;
  return Object.entries(variables).reduce((result, [key, replacement]) => result.replaceAll(`{{${key}}}`, String(replacement)), value);
}

function translateDynamic(language: Language, text: string, translate: (key: string, variables?: Record<string, string | number>) => string) {
  const exact = dictionaries[language][text];
  if (exact || language === "ru") return exact ?? text;

  const ndviEvidence = text.match(/^Средний NDVI за период: (.+); изменение от первого к последнему снимку: (.+)\.$/);
  if (ndviEvidence) return language === "kk"
    ? `Кезеңдегі орташа NDVI: ${ndviEvidence[1]}; бірінші суреттен соңғысына дейінгі өзгеріс: ${ndviEvidence[2]}.`
    : `Mean NDVI for the period: ${ndviEvidence[1]}; change from first to last image: ${ndviEvidence[2]}.`;
  const ndmiEvidence = text.match(/^Средний NDMI за период: (.+); изменение от первого к последнему снимку: (.+)\.$/);
  if (ndmiEvidence) return language === "kk"
    ? `Кезеңдегі орташа NDMI: ${ndmiEvidence[1]}; бірінші суреттен соңғысына дейінгі өзгеріс: ${ndmiEvidence[2]}.`
    : `Mean NDMI for the period: ${ndmiEvidence[1]}; change from first to last image: ${ndmiEvidence[2]}.`;
  const vegetationEvidence = text.match(/^Растительный сигнал NDVI ≥ 0,30 занимает (.+)% проанализированных пикселей\.$/);
  if (vegetationEvidence) return language === "kk"
    ? `NDVI ≥ 0,30 өсімдік сигналы талданған пиксельдердің ${vegetationEvidence[1]}%-ын қамтиды.`
    : `The NDVI ≥ 0.30 vegetation signal covers ${vegetationEvidence[1]}% of analyzed pixels.`;
  const clusterEvidence = text.match(/^Неконтролируемая ML-кластеризация выделила (\d+) спектральные группы без ручных меток\.$/);
  if (clusterEvidence) return language === "kk"
    ? `Мұғалімсіз ML-кластерлеу қолмен белгілеусіз ${clusterEvidence[1]} спектрлік топты анықтады.`
    : `Unsupervised ML clustering identified ${clusterEvidence[1]} spectral groups without manual labels.`;
  const featureProgress = text.match(/^Извлечены признаки за месяц (\d+): (\d+) пикселей$/);
  if (featureProgress) return language === "kk"
    ? `${featureProgress[1]} ай үшін белгілер алынды: ${featureProgress[2]} пиксель`
    : `Features extracted for month ${featureProgress[1]}: ${featureProgress[2]} pixels`;

  const runtimeReplacements: Record<Exclude<Language, "ru">, Array<[string, string]>> = {
    kk: [
      ["уже обработан, продолжаем поиск", "өңделген, іздеуді жалғастырамыз"], ["поиск снимков в каталоге Copernicus", "Copernicus каталогынан суреттерді іздеу"], ["создание демонстрационного снимка", "демонстрациялық сурет жасау"], ["снимок выбран", "сурет таңдалды"], ["снимки с полным покрытием не найдены", "толық қамтылған суреттер табылмады"], ["пакетный расчёт качества для", "күндер үшін сапаны пакеттік есептеу:"], ["обработано дат —", "өңделген күндер —"], ["сохранение", "сақтау:"], ["кандидатов", "кандидат"], ["отобрано дат для композита —", "композит үшін таңдалған күндер —"], ["подходящие снимки не найдены", "қолайлы суреттер табылмады"], ["подготовка обработки NDVI", "NDVI өңдеуін дайындау"], ["нет подходящего снимка", "қолайлы сурет жоқ"], ["формирование демонстрационного растра", "демонстрациялық растр жасау"], ["загрузка спектральных данных Sentinel-2", "Sentinel-2 спектрлік деректерін жүктеу"], ["загрузка снимка", "суретті жүктеу"], ["декодирование GeoTIFF", "GeoTIFF декодтау"], ["расчёт статистики и классов NDVI", "NDVI статистикасы мен кластарын есептеу"], ["сохранение растров и результатов", "растрлар мен нәтижелерді сақтау"], ["NDVI рассчитан", "NDVI есептелді"]
    ],
    en: [
      ["уже обработан, продолжаем поиск", "already processed; continuing search"], ["поиск снимков в каталоге Copernicus", "searching the Copernicus catalog"], ["создание демонстрационного снимка", "creating demo imagery"], ["снимок выбран", "image selected"], ["снимки с полным покрытием не найдены", "no full-coverage images found"], ["пакетный расчёт качества для", "batch quality calculation for"], ["обработано дат —", "dates processed —"], ["сохранение", "saving"], ["кандидатов", "candidates"], ["отобрано дат для композита —", "dates selected for the composite —"], ["подходящие снимки не найдены", "no suitable images found"], ["подготовка обработки NDVI", "preparing NDVI processing"], ["нет подходящего снимка", "no suitable image"], ["формирование демонстрационного растра", "building demo raster"], ["загрузка спектральных данных Sentinel-2", "downloading Sentinel-2 spectral data"], ["загрузка снимка", "downloading image"], ["декодирование GeoTIFF", "decoding GeoTIFF"], ["расчёт статистики и классов NDVI", "calculating NDVI statistics and classes"], ["сохранение растров и результатов", "saving rasters and results"], ["NDVI рассчитан", "NDVI calculated"]
    ]
  };
  let result = text;
  Object.entries(months.ru).forEach(([month, name]) => { result = result.replace(name, months[language][Number(month)] ?? name); });
  runtimeReplacements[language].forEach(([source, target]) => { result = result.replace(source, target); });
  return result === text ? translate(text) : result;
}

interface I18nValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (key: string, variables?: Record<string, string | number>) => string;
  monthName: (month: number) => string;
  formatNumber: (value: number | null | undefined, digits?: number) => string;
  formatDate: (value: string | null | undefined) => string;
  translateRuntime: (value: string | null | undefined) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>("ru");

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === "ru" || stored === "kk" || stored === "en") setLanguageState(stored);
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const value = useMemo<I18nValue>(() => {
    const translate = (key: string, variables?: Record<string, string | number>) => interpolate(dictionaries[language][key] ?? key, variables);
    const setLanguage = (next: Language) => {
      setLanguageState(next);
      localStorage.setItem(STORAGE_KEY, next);
    };
    return {
      language,
      setLanguage,
      t: translate,
      monthName: (month) => months[language][month] ?? String(month),
      formatNumber: (number, digits = 2) => number == null ? "—" : new Intl.NumberFormat(locales[language], { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(number),
      formatDate: (date) => date ? new Intl.DateTimeFormat(locales[language], { day: "2-digit", month: "short", year: "numeric" }).format(new Date(date)) : translate("Нет данных"),
      translateRuntime: (text) => text ? translateDynamic(language, text, translate) : ""
    };
  }, [language]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used within I18nProvider");
  return value;
}
